const _ = require('lodash');
const constant = require('../lib/constant');

/**
 * sortedset:
 * zadd key score member [[score member] [score member] ...]
 * zcard key
 * zcount key min max
 * zincrby key increment member
 * zrange key start stop [WITHSCORES]
 * zrangebyscore key min max [WITHSCORES] [LIMIT offset count]
 * zrank key member
 * zrem key member [member ...]
 * zremrangebyrank key start stop
 * zremrangebyscore key min max
 * zrevrange key start stop [WITHSCORES]
 * zrevrangebyscore key max min [WITHSCORES] [LIMIT offset count]
 * zrevrank key member
 * zscore key member
 */
module.exports = (common) => {
  const operations = {
    // eslint-disable-next-line no-unused-vars
    * zadd(key, ...kvs) {
      return yield common.zAddOrIncrement(false, ...arguments);
    },

    * zcard(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return 0;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj && origObj.h && _.isObject(origObj.h)) {
        return Object.keys(origObj.h).length;
      }
      /* istanbul ignore next */
      return 0;
    },

    * zcount(key, min, max, forceMaster) {
      const memberArray = yield operations.zrangebyscore(key, min, max, forceMaster);
      if (memberArray === undefined) {
        return undefined;
      }
      if (_.isArray(memberArray)) {
        return memberArray.length;
      }
      /* istanbul ignore next */
      return 0;
    },

    // eslint-disable-next-line no-unused-vars
    * zincrby(key, increment, member) {
      return yield common.zAddOrIncrement(true, ...arguments);
    },

    * zrange(key, start, stop, WITHSCORES, forceMaster) {
      let withscores = false;
      if (WITHSCORES === constant.CONSTANT.WITHSCORES) {
        withscores = true;
      } else if (WITHSCORES === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
      }
      console.log('--zrange', key, start, stop, WITHSCORES, forceMaster);
      console.log('--withscores', withscores, 'forceMaster', forceMaster);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return [];
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (!origObj || !_.isObject(origObj.h)) {
        return [];
      }
      const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
      const memberSize = Object.keys(origHash).length;
      /* istanbul ignore if */
      if (memberSize === 0) {
        return [];
      }
      start = common.convertToInt(start);
      stop = common.convertToInt(stop);
      /* istanbul ignore next */
      if (start < 0) {
        start = memberSize + start;
      } else if (start >= memberSize) {
        return [];
      }
      /* istanbul ignore next */
      if (stop >= memberSize) {
        stop = memberSize;
      } else if (stop < -memberSize) {
        stop = 0;
      } else if (stop < 0) {
        stop = memberSize + stop;
      }
      /* istanbul ignore if */
      if (start > stop) {
        return [];
      }
      let rank = 0;
      const result = [];
      const memberArrays = _.values(origSet);
      for (let i = 0; i < memberArrays.length; i++) {
        const memberArray = memberArrays[i];
        for (let j = 0; j < memberArray.length; j++) {
          if (rank > stop) {
            return result;
          }
          const member = memberArray[j];
          if (rank >= start) {
            if (origDict[member]) {
              result.push(origDict[member]);
            } else {
              result.push(member);
            }
            if (withscores) {
              result.push(common.convertToInt(origHash[member]));
            }
          }
          rank++;
        }
      }
      /* istanbul ignore next */
      return result;
    },

    // eslint-disable-next-line no-unused-vars
    * zrangebyscore(key, MIN, MAX, WITHSCORES, LIMIT, OFFSET, COUNT) {
      const ret = yield common.zrangebyscoreWithTotal(...arguments);
      if (ret === undefined) {
        return undefined;
      }
      return ret.data;
    },

    * zrank(key, member, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || member === null || member === undefined) {
        return null;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj === null) {
        return null;
      }
      if (_.isObject(member)) {
        member = common.hash(member);
      }
      let score = origObj.h[member];
      /* istanbul ignore if */
      if (score === null || score === undefined) {
        return null;
      }
      score = common.convertToInt(score);
      const origSet = origObj.s;
      const scoreArray = Object.keys(origSet);
      let rank = 0;
      for (let i = 0; i < scoreArray.length; i++) {
        const s = common.convertToInt(scoreArray[i]);
        const memberArray = origSet[s];
        const memberSize = memberArray.length;
        if (s < score) {
          rank += memberSize;
        } else if (s === score) {
          for (let j = 0; j < memberSize; j++) {
            if (member > memberArray[j]) {
              rank++;
            } else {
              break;
            }
          }
        } else {
          break;
        }
      }
      return rank;
    },

    * zrem(key, ...member) {
      const members = common.getFieldToArray(member);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || members === null) {
        return 0;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.ZSET, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null) {
          return 0;
        }
        const origObj = objVer.value;

        const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
        let count = 0;
        members.forEach(member => {
          if (_.isObject(member)) {
            member = common.hash(member);
          }
          let score = origHash[member];
          if (score !== null && score !== undefined) {
            score = common.convertToInt(score);
            const memberArray = origSet[score];
            if (_.isArray(memberArray) && memberArray.length) {
              for (let i = 0; i < memberArray.length; i++) {
                if (_.isEqual(memberArray[i], member)) {
                  memberArray.splice(i, 1);
                  delete origHash[member];
                  delete origDict[member];
                  count++;
                  break;
                }
              }
            }
            if (!memberArray.length) {
              delete origSet[score];
            }
          }
        });
        const ret = yield common.setStringEx(key, common.toStringWithType(origObj, constant.TYPE.ZSET), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return count;
        }
      }
      /* istanbul ignore next */
      return 0;
    },

    * zremrangebyrank(key, start, stop) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return 0;
      }
      start = common.convertToInt(start);
      stop = common.convertToInt(stop);

      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.ZSET, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null) {
          return 0;
        }
        const origObj = objVer.value;

        const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
        const memberSize = Object.keys(origHash).length;
        /* istanbul ignore next */
        if (start < 0) {
          start = memberSize + start;
        } else if (start >= memberSize) {
          return 0;
        }
        /* istanbul ignore next */
        if (stop >= memberSize) {
          stop = memberSize;
        } else if (stop < -memberSize) {
          stop = 0;
        } else if (stop < 0) {
          stop = memberSize + stop;
        }
        /* istanbul ignore if */
        if (start > stop) {
          return 0;
        }
        let count = 0;
        let rank = 0;
        let finish = false;
        const memberArrays = _.values(origSet);
        for (let i = 0; i < memberArrays.length; i++) {
          const memberArray = memberArrays[i];
          for (let j = 0; j < memberArray.length; j++) {
            if (rank > stop) {
              finish = true;
              break;
            } else if (rank >= start) {
              const member = memberArray[j];
              memberArray.splice(j--, 1);
              delete origHash[member];
              delete origDict[member];
              count++;
            }
            rank++;
          }
          if (!memberArray.length) {
            delete memberArrays[i];
          }
          if (finish) {
            break;
          }
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(origObj, constant.TYPE.ZSET), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return count;
        }
      }
      /* istanbul ignore next */
      return 0;
    },

    * zremrangebyscore(key, min, max) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return 0;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.ZSET, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null) {
          return 0;
        }
        const origObj = objVer.value;

        const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
        const scoreArray = Object.keys(origSet);
        let count = 0;
        for (let i = 0; i < scoreArray.length; i++) {
          const score = common.convertToInt(scoreArray[i]);
          if (score < min) {
            continue;
          }
          if (score > max) {
            break;
          }
          const memberArray = origSet[score];
          for (let j = 0; j < memberArray.length; j++) {
            const member = memberArray[j];
            memberArray.splice(j--, 1);
            delete origHash[member];
            delete origDict[member];

            count++;
          }
          if (!memberArray.length) {
            delete origSet[score];
          }
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(origObj, constant.TYPE.ZSET), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return count;
        }
      }
      /* istanbul ignore next */
      return 0;
    },

    * zrevrange(key, start, stop, WITHSCORES, forceMaster) {
      let withscores = false;
      if (WITHSCORES === constant.CONSTANT.WITHSCORES) {
        withscores = true;
      } else if (WITHSCORES === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
      }
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return [];
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (!origObj || !_.isObject(origObj.h)) {
        return [];
      }
      const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
      const memberSize = Object.keys(origHash).length;
      /* istanbul ignore if */
      if (memberSize === 0) {
        return [];
      }
      start = common.convertToInt(start);
      stop = common.convertToInt(stop);
      /* istanbul ignore next */
      if (start < 0) {
        start = memberSize + start;
      } else if (start >= memberSize) {
        return [];
      }
      /* istanbul ignore next */
      if (stop >= memberSize) {
        stop = memberSize;
      } else if (stop < -memberSize) {
        stop = 0;
      } else if (stop < 0) {
        stop = memberSize + stop;
      }
      /* istanbul ignore if */
      if (start > stop) {
        return [];
      }

      let rank = 0;
      const result = [];
      const memberArrays = _.values(origSet);
      for (let i = memberArrays.length - 1; i >= 0; i--) {
        const memberArray = memberArrays[i];
        for (let j = memberArray.length - 1; j >= 0; j--) {
          if (rank > stop) {
            return result;
          }
          const member = memberArray[j];
          if (rank >= start) {
            if (origDict[member]) {
              result.push(origDict[member]);
            } else {
              result.push(member);
            }
            if (withscores) {
              result.push(common.convertToInt(origHash[member]));
            }
          }
          rank++;
        }
      }
      /* istanbul ignore next */
      return result;
    },

    // eslint-disable-next-line no-unused-vars
    * zrevrangebyscore(key, MAX, MIN, WITHSCORES, LIMIT, OFFSET, COUNT) {
      const ret = yield common.zrevrangebyscoreWithTotal(...arguments);
      if (ret === undefined) {
        return undefined;
      }
      return ret.data;
    },

    * zrevrank(key, member, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || member === null || member === undefined) {
        return null;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj === null) {
        return null;
      }
      if (_.isObject(member)) {
        member = common.hash(member);
      }
      let score = origObj.h[member];
      /* istanbul ignore if */
      if (score === null || score === undefined) {
        return null;
      }
      score = common.convertToInt(score);
      const origSet = origObj.s;
      const scoreArray = Object.keys(origSet);
      let rank = 0;
      for (let i = scoreArray.length - 1; i >= 0; i--) {
        const s = common.convertToInt(scoreArray[i]);
        const memberArray = origSet[s];
        const memberSize = memberArray.length;
        if (s > score) {
          rank += memberSize;
        } else if (s === score) {
          for (let j = memberSize - 1; j >= 0; j--) {
            if (member < memberArray[j]) {
              rank++;
            } else {
              break;
            }
          }
        } else {
          break;
        }
      }
      return rank;
    },

    * zscore(key, member, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || member === null || member === undefined) {
        return null;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj === null || origObj.h === null || origObj.h === undefined) {
        return null;
      }
      if (_.isObject(member)) {
        member = common.hash(member);
      }
      const score = origObj.h[member];
      if (score === null || score === undefined) {
        return null;
      }
      return common.convertToInt(score);
    },
  };
  return operations;
};
